  Lemma dealloc_cas : ltac2:(zQ "hd7!h9!jc!imd!hs5!ii8!hrf!hnd!k1!iv9!jof!ioa!ipb!jp5!iq1!in5!kj9!kjf!ivf!ln5!kk5!kpb!ktb!li5!jo3!inc!ip4!pa!kkc!kl5&>0@1$1@1$0#k0@1$d@1$1@1$0#8&@3$3$2@1$h1@1$5?4actx@1$b$2&@3$3$2@1$h0@1$5?4size~1&@3$3$2@1$f@1$5Z~2&@3$3$2@1$8@1$9?2b1~3&@2$6@2$h8@1$0#k0?2sp-op0&@2$a@1$0#k0~5>2x1@1$1@1$0#k0>2t0@1$1@1$0#k0>2t1@1$1@1$0#k0>2t2@1$1@1$0#k0>3xa0@1$1@1$0#k0>3xa1@1$1@1$0#k0>3xa2@1$1@1$0#k0>3xa3@1$1@1$0#k0>3xa4@1$1@1$0#k0>3xa5@1$1@1$0#k0>3xa6@1$1@1$0#k0>3xa7@1$1@1$0#k0>2t3@1$1@1$0#k0>2t4@1$1@1$0#k0>2t5@1$1@1$0#k0>2t6@1$1@1$0#k0>3xs0@1$1@1$0#k0>3xs1@1$1@1$0#k0>3xs3@1$1@1$0#k0>3xs4@1$1@1$0#k0>3xs5@1$1@1$0#k0>3xs6@1$1@1$0#k0>2m0~0>1Q>0$haP>0@2$h5$4^2>0@4$h7$4^3@2$6?1U-h0@3$3$2@1$8@1$9+2~4>0>3ya0@1$1@1$0#k0>3ya1@1$1@1$0#k0>3ya2@1$1@1$0#k0>3ya3@1$1@1$0#k0>3ya4@1$1@1$0#k0>3ya5@1$1@1$0#k0>3ya6@1$1@1$0#k0>3ya7@1$1@1$0#k0>2m1~0>0@2$h5$4^1>0@3$hb@3$3@2$e$7$7@4$h9$7$7@2$6?1U-h0@2$6?1U-c@1$b@2$e$7$7^e^2>0@3$hc$4^f^3>0@4$h7$4^4@2$6?1U-h0@3$3$2@1$8@1$9+3~4@3$h2$4^h0@7$h4@hf$h3^i7~6?2gp?2tp^i6^i5^i4^h7^h6^d^c^b^a^9^8^7^6@1$5@2$6?1U-h0^h5^h4^h3^h2?2s7?2s8?2s9?3s10?3s11^hb^ha^h9^h8?1F@2$a@1$0#k0+moujc?2fc@1$c@1$1@1$0#k0^5@1$h6$4@3$h2$4^4@7$h4@hf$h3^hb~6?2gp?2tp^ha^h9^h8^b^a^h7^h6^h5^h4^h3^h2^h1^h0@1$5@2$6?1U-h0^9^8^7^6?2s7?2s8?2s9?3s10?3s11^f^e^d^c?1F@2$a@1$0#k0+motvc?2fc@1$c@1$1@1$0#k0^5@1$h6$4").
Proof.
Ltac litx := repeat match goal with
      | |- context [Z_to_bv 64 (bv_swrap ?n ?x)] => let v := eval vm_compute in (bv_swrap n x) in change (bv_swrap n x) with v
      | |- context [Z_to_bv 64 (Z.land ?x ?y)] => let v := eval vm_compute in (Z.land x y) in change (Z.land x y) with v
      | |- context [Z_to_bv 64 (Z.lxor ?x ?y)] => let v := eval vm_compute in (Z.lxor x y) in change (Z.lxor x y) with v
      | |- context [Z_to_bv 64 (Z.lor ?x ?y)] => let v := eval vm_compute in (Z.lor x y) in change (Z.lor x y) with v
      | |- context [Z_to_bv 64 (Z.shiftr ?x ?y)] => let v := eval vm_compute in (Z.shiftr x y) in change (Z.shiftr x y) with v
      end.
Ltac cas_run bb HW HW0 HREST KONT MU :=
      (* [comment removed for export] *)
      astep;
      (* [comment removed for export] *)
      step; litx; step;
      let K := fresh "K" in
      if_cases K; zify_cond K; [exfalso; apply K; reflexivity|]; clear K;
      (* [comment removed for export] *)
      step; step; step; litx;
      astep;
      step; if_cases K; zify_cond K; [exfalso; apply K; reflexivity|]; clear K;
      apply (rw_cells_reshape _ _ _ [C1 (b8 3); C1 (b8 bb); C2 (Z_to_bv 64 0)]) in HW0; [| symmetry; apply (HW 3); lia| reflexivity| cbn; repeat split; exact I];
